INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (1, 'The Plaza', 'New York', 'United States', '768 Fifth Avenue, New York, NY 10019', 40.764528, -73.974444, 5, 'A French Renaissance château on Fifth Avenue at Central Park South, opened in 1907 and now a National Historic Landmark. Rooms look out over the park or the avenue, and the lobby still feels like the city''s front parlour.', ARRAY['Central Park views', 'Afternoon tea', 'Spa', 'Fitness centre', 'Concierge', '24-hour room service']::text[], ARRAY['hotels/the-plaza-exterior', 'photos/QJMKyrud5l8', 'photos/PibraWHb4h8', 'photos/A2CChTZvzTE']::text[], 'https://www.wikidata.org/wiki/Q1066676');
INSERT INTO room_types (id, hotel_id, name, description, bed, size_sqm, max_guests, image, rooms_per_night) VALUES (101, 1, 'Deluxe King', 'A quiet courtyard-facing room with a king bed, writing desk and marble bathroom.', 'King', 34, 2, 'photos/2P_ifaetDm0', 40);
