INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (2, 'The Algonquin Hotel', 'New York', 'United States', '59 West 44th Street, New York, NY 10036', 40.755833, -73.982333, 4, 'A Midtown institution on West 44th Street, once home to the Round Table of writers and critics. The lobby is made for lingering, a few minutes'' walk from the Broadway theatres.', ARRAY['Historic lobby bar', 'Theatre district', 'Fitness centre', 'Pet friendly']::text[], ARRAY['hotels/algonquin-exterior', 'photos/1CcryZiF2PA', 'photos/6BJu73-UJpg', 'photos/A2CChTZvzTE']::text[], 'https://www.wikidata.org/wiki/Q689447');
INSERT INTO room_types (id, hotel_id, name, description, bed, size_sqm, max_guests, image, rooms_per_night) VALUES (201, 2, 'Classic Queen', 'Compact and well considered, with a queen bed and city views.', 'Queen', 22, 2, 'photos/uocSnWMhnAs', 40);
