INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (3, 'Hôtel Lutetia', 'Paris', 'France', '45 Boulevard Raspail, 75006 Paris', 48.851354, 2.327203, 5, 'The only grand palace hotel on the Left Bank, opened in 1910 on Boulevard Raspail facing the Square Boucicaut. Its Art Nouveau façade gives way to quiet rooms in Saint-Germain-des-Prés.', ARRAY['Saint-Germain-des-Prés', 'Spa and pool', 'Jazz bar', 'Restaurant', 'Concierge']::text[], ARRAY['hotels/lutetia-exterior', 'photos/1CcryZiF2PA', 'photos/q-LqibnwN8Y', 'photos/t9Td0zfDTwI']::text[], 'https://www.wikidata.org/wiki/Q1515595');
