INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (4, 'Hôtel Raphael', 'Paris', 'France', '17 Avenue Kléber, 75116 Paris', 48.87136, 2.293706, 5, 'A family-run hotel from 1925 on Avenue Kléber, a short walk from the Arc de Triomphe. Expect wood panelling, antique furniture and a rooftop terrace overlooking the city.', ARRAY['Rooftop terrace', 'Near Arc de Triomphe', 'Bar', 'Restaurant']::text[], ARRAY['hotels/raphael-exterior', 'photos/QJMKyrud5l8', 'photos/PibraWHb4h8', 'photos/t9Td0zfDTwI']::text[], 'https://www.wikidata.org/wiki/Q3145649');
