INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (5, 'Pestana Palace Lisboa', 'Lisbon', 'Portugal', 'Rua Jau 54, 1300-314 Lisboa', 38.703781, -9.186828, 5, 'A restored early-twentieth-century palace set in its own gardens in Alto de Santo Amaro, above the Tagus. Rooms sit in the palace and its newer wings around a garden pool.', ARRAY['Palace gardens', 'Outdoor pool', 'Spa', 'Free parking', 'Restaurant']::text[], ARRAY['hotels/pestana-palace-exterior', 'photos/QJMKyrud5l8', 'photos/hYexJa2IrVo', 'photos/VHWyqXsWHg0']::text[], 'https://www.wikidata.org/wiki/Q10343981');
