INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (6, 'Bairro Alto Hotel', 'Lisbon', 'Portugal', 'Praça Luís de Camões 2, 1200-243 Lisboa', 38.710299, -9.143315, 5, 'An eighteenth-century building on Praça Luís de Camões, where Chiado meets Bairro Alto. The rooftop terrace looks over the river, and the trams run past the front door.', ARRAY['Rooftop terrace', 'River views', 'Restaurant', 'Chiado location']::text[], ARRAY['hotels/bairro-alto-hotel-exterior', 'photos/1CcryZiF2PA', 'photos/q-LqibnwN8Y', 'photos/VHWyqXsWHg0']::text[], 'https://www.wikidata.org/wiki/Q73760891');
