INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (7, 'The Westin Miyako Kyoto', 'Kyoto', 'Japan', '1 Awataguchi Kachōchō, Higashiyama-ku, Kyoto 605-0052', 35.008861, 135.787944, 5, 'Founded in 1900 on the forested slopes of Higashiyama, a short walk from Nanzen-ji and the Philosopher''s Path. Rooms look across the city or into the hotel''s own gardens.', ARRAY['Japanese gardens', 'Spa', 'Indoor pool', 'Near Nanzen-ji', 'Restaurants']::text[], ARRAY['hotels/westin-miyako-kyoto-exterior', 'photos/QJMKyrud5l8', 'photos/hYexJa2IrVo', 'photos/_UIN-pFfJ7c']::text[], 'https://www.wikidata.org/wiki/Q11288502');
