INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (8, 'Hyatt Regency Kyoto', 'Kyoto', 'Japan', '644-2 Sanjūsangendō-mawari, Higashiyama-ku, Kyoto 605-0941', 34.988556, 135.773361, 4, 'Across the street from Sanjūsangen-dō temple in Higashiyama, opened in 2006. Kyoto textiles and woodwork set the tone, and Gion is a short walk north.', ARRAY['Opposite Sanjūsangen-dō', 'Spa', 'Fitness centre', 'Restaurants']::text[], ARRAY['hotels/hyatt-regency-kyoto-exterior', 'photos/1CcryZiF2PA', 'photos/6BJu73-UJpg', 'photos/_UIN-pFfJ7c']::text[], 'https://www.wikidata.org/wiki/Q11325962');
