INSERT INTO hotels (id, name, city, country, address, latitude, longitude, star_rating, description, amenities, images, source_url) VALUES (9, 'Hilton Cape Town City Centre', 'Cape Town', 'South Africa', '126 Buitengracht Street, Cape Town City Centre, 8001', -33.921631, 18.415853, 4, 'On Buitengracht Street in the City Bowl, opened in 2011, with Table Mountain behind and the colourful houses of Bo-Kaap next door. The V&A Waterfront is ten minutes away.', ARRAY['Table Mountain views', 'Outdoor pool', 'Fitness centre', 'Restaurant', 'Parking']::text[], ARRAY['hotels/hilton-cape-town-exterior', 'photos/QJMKyrud5l8', 'photos/q-LqibnwN8Y', 'photos/bVovHygDlJI']::text[], 'https://www.wikidata.org/wiki/Q60452089');
